L=['# May 2026 · Eight original Mains frameworks','','Original planning aids, not official answers or predictions. Anchor each argument in its source/date and preserve open implementation questions.']
for i,title,pts in F:
 n=N[ref(i)];L+=['','## '+title,'','**Study reference:** '+n['id'],'','**Dated anchor:** '+n['why'],'']+[f'{j}. {t}' for j,t in enumerate(pts,1)]+['','**Evidence caution:** '+n['trap'],'','**Conclusion test:** Identify a responsible institution, an implementation safeguard and a measurable outcome.']
(R/'volumes/May-2026-Mains-Frameworks.md').write_text('\n'.join(L)+'\n')
